import fs from "node:fs";
import path from "node:path";
import { app, nativeImage, type NativeImage } from "electron";

/**
 * Template (monochrome) icons for the native app-menu items. macOS tints
 * templates to match the menu bar in light/dark mode; the Windows/Linux menu
 * bars draw no item icons, so attaching them there is a harmless no-op.
 * Generated by scripts/generate-menu-icons.mjs (part of the `icons` script)
 * and shipped as extraResources — in dev checkouts they sit in build/.
 */
export interface MenuIcons {
  about?: NativeImage;
  checkUpdates?: NativeImage;
  promptPalette?: NativeImage;
  settings?: NativeImage;
  tray?: NativeImage;
}

function menuIconsDir(): string | null {
  const candidates = [
    path.join(process.resourcesPath, "menu-icons"),
    path.join(app.getAppPath(), "build", "menu-icons"),
  ];
  return candidates.find((candidate) => fs.existsSync(path.join(candidate, "about.png"))) ?? null;
}

function loadTemplateIcon(dir: string, name: string): NativeImage | undefined {
  // Picks up the @2x variant automatically for retina.
  const image = nativeImage.createFromPath(path.join(dir, `${name}.png`));
  if (image.isEmpty()) return undefined;
  image.setTemplateImage(true);
  return image;
}

export function loadMenuIcons(): MenuIcons {
  const dir = menuIconsDir();
  if (!dir) {
    console.log("[main] menu icons not found (run `pnpm --filter @promptbr0/desktop icons`) — text-only menu");
    return {};
  }
  const icons: MenuIcons = {
    about: loadTemplateIcon(dir, "about"),
    checkUpdates: loadTemplateIcon(dir, "check-updates"),
    promptPalette: loadTemplateIcon(dir, "prompt-palette"),
    settings: loadTemplateIcon(dir, "settings"),
    tray: loadTemplateIcon(dir, "tray"),
  };
  console.log(`[main] menu icons loaded from ${dir}`);
  return icons;
}

/**
 * Tray icon. macOS menu bars need a black-alpha template (the system tints it
 * for light/dark), while Windows/Linux taskbars show the icon as-is — a black
 * glyph would vanish on a dark taskbar there, so those platforms get the color
 * brand icon shipped as an extraResource (`build/` in dev checkouts). Windows
 * prefers the multi-size ICO so high-DPI notification areas stay sharp.
 */
export function loadTrayIcon(platform: NodeJS.Platform): NativeImage | string | undefined {
  if (platform === "darwin") {
    const dir = menuIconsDir();
    return dir ? loadTemplateIcon(dir, "tray") : undefined;
  }
  const candidates = (fileName: string): string[] => [
    path.join(process.resourcesPath, fileName),
    path.join(app.getAppPath(), "build", fileName),
  ];
  if (platform === "win32") {
    return candidates("icon.ico").find((candidate) => fs.existsSync(candidate));
  }
  const file = candidates("icon.png").find((candidate) => fs.existsSync(candidate));
  if (!file) return undefined;
  const image = nativeImage.createFromPath(file);
  if (image.isEmpty()) return undefined;
  return image.resize({ width: 22, height: 22 });
}
